/**
 * Who can generate a report. A report on a project is generated by people who
 * can edit or review that project; someone who can only read it is refused,
 * and the screen has to say so in plain words rather than show the database's
 * message (see `isPermissionDenied` and the report page).
 */
import type { Client } from 'pg'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'

import { prepareTestDatabase } from './helpers'

const WS = '00000000-0000-4000-8000-0000000d6a01'
const PROJECT = '00000000-0000-4000-8000-0000000d6a02'
const OWNER = 'rga-owner'
const EDITOR = 'rga-editor'
const REVIEWER = 'rga-reviewer'
const VIEWER = 'rga-viewer'

let migrator: Client
let asRole: (role: 'authenticator') => Promise<Client>
const clients: Client[] = []
let reportId = ''
let looseReportId = ''

async function as(userId: string): Promise<Client> {
  const client = await asRole('authenticator')
  clients.push(client)
  await client.query('SET ROLE authenticated')
  await client.query("SELECT set_config('request.jwt.claims', $1, false)", [
    JSON.stringify({ sub: userId, workspace_id: WS, role: 'authenticated' }),
  ])
  return client
}

function generate(client: Client, id: string) {
  return client.query('SELECT id FROM api.generate_report($1, $2, $3)', [
    WS,
    id,
    'html',
  ])
}

beforeAll(async () => {
  ;({ migrator, asRole } = await prepareTestDatabase())
  await migrator.query(
    `INSERT INTO internal.user (id, name, email, "emailVerified") VALUES
      ('${OWNER}', 'Owner', 'rga-owner@sheetbase.test', true),
      ('${EDITOR}', 'Editor', 'rga-editor@sheetbase.test', true),
      ('${REVIEWER}', 'Reviewer', 'rga-reviewer@sheetbase.test', true),
      ('${VIEWER}', 'Viewer', 'rga-viewer@sheetbase.test', true);
     INSERT INTO api.workspaces (id, slug, name) VALUES ('${WS}', 'rga', 'RGA');
     INSERT INTO api.workspace_memberships (workspace_id, user_id, role) VALUES
      ('${WS}', '${OWNER}', 'owner'),
      ('${WS}', '${EDITOR}', 'scientist'),
      ('${WS}', '${REVIEWER}', 'scientist'),
      ('${WS}', '${VIEWER}', 'scientist');
     INSERT INTO api.projects (id, workspace_id, key, title, lead_user_id)
      VALUES ('${PROJECT}', '${WS}', 'rga', 'RGA project', '${OWNER}');
     INSERT INTO api.project_access(workspace_id,project_id,user_id,can_view,can_edit,can_review,can_manage,granted_by_user_id) VALUES
      ('${WS}','${PROJECT}','${EDITOR}',true,true,false,false,'${OWNER}'),
      ('${WS}','${PROJECT}','${REVIEWER}',true,false,true,false,'${OWNER}'),
      ('${WS}','${PROJECT}','${VIEWER}',true,false,false,false,'${OWNER}');`,
  )

  const owner = await as(OWNER)
  const made = await owner.query(
    'SELECT id::text, record_id::text FROM api.create_report_definition($1, $2)',
    [WS, 'Access check'],
  )
  const loose = await owner.query(
    'SELECT id::text FROM api.create_report_definition($1, $2)',
    [WS, 'Access check, no project'],
  )

  reportId = made.rows[0].id
  looseReportId = loose.rows[0].id
  await owner.query(
    `SELECT id FROM api.add_report_section($1, $2, 'Summary', 'Text', 'text', 'free_text')`,
    [WS, reportId],
  )
  await migrator.query(
    `UPDATE api.records SET project_id='${PROJECT}' WHERE id='${made.rows[0].record_id}';
     UPDATE api.report_definitions SET project_id='${PROJECT}' WHERE id='${reportId}';`,
  )
})

afterAll(async () => {
  for (const client of clients) await client.end()
  await migrator.end()
})

describe('generating a report on a project', () => {
  it.each([OWNER, EDITOR, REVIEWER])(
    'lets %s, who can edit or review the project',
    async (id) => {
      const rows = (await generate(await as(id), reportId)).rows

      expect(rows).toHaveLength(1)
    },
  )

  it.each([VIEWER])(
    'refuses %s, who can only read it, with a permission error the screen can name',
    async (id) => {
      const client = await as(id)

      await expect(generate(client, reportId)).rejects.toMatchObject({
        code: '42501',
        message: 'Object access denied',
      })
      // They can still read what was generated.
      const seen = await client.query(
        'SELECT id FROM api.report_definitions WHERE id=$1',
        [reportId],
      )

      expect(seen.rows).toHaveLength(1)
    },
  )

  it('still keeps a reviewer from changing the report itself', async () => {
    await expect(
      (await as(REVIEWER)).query(
        `SELECT id FROM api.add_report_section($1, $2, 'Extra', 'Text', 'text', 'free_text')`,
        [WS, reportId],
      ),
    ).rejects.toMatchObject({ code: '42501' })
  })

  it('lets a workspace writer generate a report that belongs to no project', async () => {
    expect((await generate(await as(EDITOR), looseReportId)).rows).toHaveLength(
      1,
    )
  })
})
